def hook(ctx, nb):
    stage = nb.get('stage', '')
    target = nb.get('target_type') or text(getv(ctx, 'task.target_type', ''))
    dest = nb.get('destination_type') or text(getv(ctx, 'task.destination_type', ''))
    verb = nb.get('required_verb') or needverb(nb.get('task_type', ''))
    tt = nb.get('task_type', '')
    msg = ''
    if stage == 'wrong_inventory':
        msg = 'Inventory does not match the requested target type. Do not place a wrong object; recover by setting it down only if needed, then find the requested target.'
    elif stage == 'transform' and verb and target:
        msg = 'You are carrying the target but must ' + verb + ' it before placing. Use the admissible ' + verb + ' action with the proper appliance, then go to the destination.'
    elif stage == 'put_target' and target and dest:
        msg = 'The target is ready. Use the admissible put action for the target at the requested ' + dest + ', not a different receptacle.'
    elif stage == 'go_destination' and target and dest:
        msg = 'Carry the target to the requested ' + dest + ' and put it there; avoid putting it on unrelated surfaces.'
    elif stage == 'take_target' and target:
        msg = 'A requested target is available. Take the target type, not a different object type.'
    elif stage == 'find_target' and 'pick_two' in tt and nb.get('placed_count', 0) > 0:
        msg = 'One target is already placed. Leave it there, find another target of the same type, and use the same destination.'
    if not msg:
        return None
    key = stage + ':' + msg[:60]
    if nb.get('last_hint') == key:
        return None
    nb['last_hint'] = key
    return {'message': msg}

