def hook(ctx, nb):
    tt = text(getv(ctx, 'task.task_type', nb.get('task_type', '')))
    target = text(getv(ctx, 'task.target_type', nb.get('target_type', '')))
    dest = text(getv(ctx, 'task.destination_type', nb.get('destination_type', '')))
    verb = nb.get('required_verb') or needverb(tt)
    act = text(getv(ctx, 'action.final_action', getv(ctx, 'action.normalized', getv(ctx, 'action.raw', ''))))
    if not act:
        return None
    if 'pick_two' in tt and target and act.startswith('take ') and target in act:
        items = getv(ctx, 'world.placed_items', [])
        if isinstance(items, (list, tuple, set)):
            for item in items:
                itemtext = text(item)
                if itemtext and itemtext in act:
                    return {'kind': 'block_and_prompt', 'message': 'Do not take back a target already placed for the two-object task. Find another target of the same type instead.'}
    if target and act.startswith('put ') and target not in act:
        return {'kind': 'block_and_prompt', 'message': 'This is not the requested target type. Do not place a wrong object; find the requested target type.'}
    if target and dest and act.startswith('put ') and target in act and dest not in act and verb and not nb.get('transformed'):
        return {'kind': 'block_and_prompt', 'message': 'Do not place the target yet. First perform the required ' + verb + ' action, then put it at the requested destination.'}
    return None
